/// Write a rsthon function to identify non-prime numbers.
fn is_not_prime(n: isize) -> bool {
    let mut result = false;
    for i in 2..n {
        if n % i == 0 {
            result = true;
        }
    }
    result
}

/// Write a function to find the n largest integers from a given vector of numbers, returned in descending order.
fn heap_queue_largest(nums: Vec<isize>, n: isize) -> Vec<isize> {
    let mut largest_nums: Vec<isize> = nums;
    largest_nums.sort();
    largest_nums.reverse();
    largest_nums[0..n as usize].to_vec()
}

/// Write a rsthon function to check whether the two numbers differ at one bit position only or not.
fn differ_At_One_Bit_Pos(a: isize, b: isize) -> bool {
    if a == b {
        return false;
    }
    return (a ^ b).count_ones() == 1;
}

/// Write a function to find squares of individual elements in a vector.
fn square_nums(nums: Vec<isize>) -> Vec<isize> {
    nums.iter().map(|x| x * x).collect()
}

/// Write a rsthon function to remove first and last occurrence of a given character from the string.
fn remove_Occ(s: String, ch: String) -> String {
    let mut s = s;
    s = s.replace(ch.as_str(), "");
    s = s.replace(ch.as_str(), "");
    s
}

/// Write a function to sort a given matrix in ascending order according to the sum of its rows.
fn sort_matrix(M: Vec<Vec<isize>>) -> Vec<Vec<isize>> {
    let mut m = M.clone();
    m.sort_by(|a, b| a.iter().sum::<isize>().cmp(&b.iter().sum::<isize>()));
    m
}

/// Write a rsthon function to find the volume of a triangular prism.
fn find_Volume(l: isize, b: isize, h: isize) -> isize {
    (l * b * h) / 2
}

/// Write a function that returns the perimeter of a square given its side length as input.
fn square_perimeter(a: isize) -> isize {
    4 * a
}

/// Write a function to remove characters from the first string which are present in the second string.
fn remove_dirty_chars(string: String, second_string: String) -> String {
	let mut dirty_chars: Vec<char> = second_string.chars().collect();
	let mut result: String = String::new();
	let mut char_count: [u8; 128] = [0; 128];
	for c in dirty_chars.iter() {
		char_count[*c as usize] = 1;
	}

	for c in string.chars() {
		if char_count[c as usize] == 0 {
			result.push(c);
		}
	}

	result
}

/// Write a function to find whether a given vector of integers contains any duplicate element.
fn test_duplicate(arraynums: Vec<isize>) -> bool {
    let nums_set = arraynums.clone().into_iter().collect::<std::collections::HashSet<isize>>();
    arraynums.len() != nums_set.len()
}

/// Write a function to check if the given number is woodball or not.
fn is_woodall(x: isize) -> bool {
    if x % 2 == 0 {
        return false;
    }
    let mut x = x + 1;
    let mut p = 0;
    while x % 2 == 0 {
        x = x / 2;
        p = p + 1;
        if p == x {
            return true;
        }
    }
    false
}

/// Write a rsthon function to find the largest number that can be formed with the given vector of digits.
fn find_Max_Num(arr: Vec<isize>) -> isize {
    let mut arr: Vec<_> = arr.iter().map(|x| *x).collect();
    arr.sort_by(|a, b| b.cmp(a));
    let mut num = 0;
    for i in 0..arr.len() {
        num = num * 10 + arr[i];
    }
    return num;
}

/// Write a rsthon function to check whether the given two integers have opposite sign or not.
fn opposite_Signs(x: isize, y: isize) -> bool {
    (x ^ y) < 0
}

/// Write a function to find the nth octagonal number.
fn is_octagonal(n: isize) -> isize {
	3 * n * n - 2 * n
}

/// Write a rsthon function to find smallest number in a vector.
fn smallest_num(xs: Vec<isize>) -> isize {
    xs.iter().fold(isize::MAX, |a, &b| a.min(b))
}

/// Write a function to find the maximum difference between available pairs in the given tuple vector.
fn max_difference(test_list: Vec<(isize, isize)>) -> isize {
    let mut temp: Vec<isize> = Vec::new();

    for (a, b) in test_list.iter() {
        temp.push((b - a).abs());
    }

    *temp.iter().max().unwrap()
}

/// Write a function to sort a vector of tuples using the second value of each tuple.
fn subject_marks(subjectmarks: Vec<(String, isize)>) -> Vec<(String, isize)> {
    let mut subject_marks = subjectmarks;
    subject_marks.sort_by_key(|k| k.1);
    subject_marks
}

/// Write a rsthon function to count the number of positive numbers in a vector.
fn pos_count(list: Vec<isize>) -> isize {
  let mut pos_count = 0;
  for num in list {
    if num >= 0 {
      pos_count += 1;
    }
  }
  pos_count
}

/// Write a rsthon function to check whether the given vector is monotonic or not.
fn is_Monotonic(A: Vec<isize>) -> bool {
    if A.len() == 1 {
        return true;
    }
    let mut incr = true;
    let mut decr = true;
    for i in 0..A.len() - 1 {
        if A[i] > A[i + 1] {
            incr = false;
        }
        if A[i] < A[i + 1] {
            decr = false;
        }
    }
    (incr || decr)
}

/// Write a function to check whether a vector contains the given subvector or not.
fn is_sublist(l: Vec<isize>, s: Vec<isize>) -> bool {
    if s.is_empty() { return true; }

    for (i, &x) in l.iter().enumerate() {
        if s[0] == x {
            let mut n = 1;
            while n < s.len() && l[i+n] == s[n] {
                n += 1;
            }
            if n == s.len() {
                return true;
            }
        }
    }
    return false;
}

/// Write a function to find whether all the given vectors have equal length or not.
fn get_equal(Input: Vec<Vec<isize>>) -> bool {
    Input.iter().fold(true, |f, tuple| f & (tuple.len() == Input[0].len()))
}

/// Write a rsthon function to check whether the given number can be represented as the difference of two squares or not.
fn dif_Square(n: isize) -> bool {
    n % 4 != 2
}

/// Write a function to check whether it follows the sequence given in the patterns vector.
fn is_samepatterns(colors: Vec<String>, patterns: Vec<String>) -> bool {
    if colors.len() != patterns.len() {
        return false;
    }

    let mut sdict = std::collections::HashMap::new();
    let mut pset: std::collections::HashSet<_> = patterns.iter().collect();
    let mut sset: std::collections::HashSet<_> = colors.iter().collect();

    if pset.len() != sset.len() {
        return false;
    }

    for (i, pattern) in patterns.iter().enumerate() {
        let values = sdict.entry(pattern).or_insert_with(Vec::new);
        values.push(colors[i].clone());
    }

    for values in sdict.values() {
        if values[0] != values[values.len() - 1] {
            return false;
        }
    }

    true
}

/// Write a function to find tuples which have all elements divisible by k from the given vector of tuples.
fn find_tuples(test_list: Vec<(isize, isize, isize)>, K: isize) -> Vec<(isize, isize, isize)> {
    test_list
        .into_iter()
        .filter(|(x, y, z)| x % K == 0 && y % K == 0 && z % K == 0)
        .collect()
}

/// Write a rsthon function to find whether a number is divisible by 11.
fn is_Diff(n: isize) -> bool {
    n % 11 == 0
}

/// Write a rsthon function to check whether the length of the word is odd or not.
fn word_len(s: String) -> bool {
    s.split(' ')
        .any(|word| word.len() % 2 != 0)
}

/// Write a function to find the nth tetrahedral number.
fn tetrahedral_number(n: isize) -> isize {
  (n * (n + 1) * (n + 2)) / 6
}

/// Write a function to find the nth number in the newman conway sequence.
fn sequence(n: isize) -> isize {
    if n == 1 || n == 2 {
        return 1;
    } else {
        return sequence(sequence(n - 1)) + sequence(n - sequence(n - 1));
    }
}

/// Write a function to find nth centered hexagonal number.
fn centered_hexagonal_number(n: isize) -> isize {
    3 * n * (n - 1) + 1
}

