/// Write a function to get the frequency of all the elements in a vector, returned as a HashMap.
fn freq_count(list1: Vec<isize>) -> HashMap<isize, isize> {
    let mut freq_count = HashMap::new();
    for i in &list1 {
        *freq_count.entry(*i).or_insert(0) += 1;
    }
    freq_count
}

