/// Write a function to check whether the given number is undulating or not.
fn is_undulating(n: isize) -> bool {
    if n > 0 {
        let mut i = 2;
        while i < n.to_string().len() {
            if n.to_string().chars().nth(i) != n.to_string().chars().nth(i - 2) {
                return false;
            }
            i += 1;
        }
        return true;
    }
    false
}

/// Write a function to calculate the value of 'a' to the power 'b'.
fn power(a: isize, b: isize) -> isize {
    if b == 0 {
        1
    } else if a == 0 {
        0
    } else if b == 1 {
        a
    } else {
        a * power(a, b - 1)
    }
}

/// Given a vector of tuples, write a function that returns the first value of the tuple with the smallest second value.
