/// Write a function to convert the given decimal number to its binary equivalent, represented as a string with no leading zeros.
fn decimal_to_binary(n: isize) -> String {
    let mut binary_str = String::new();
    let mut n = n;
    loop {
        let rem = n % 2;
        binary_str.push_str(&rem.to_string());
        n /= 2;
        if n == 0 {
            break;
        }
    }
    binary_str.chars().rev().collect()
}

/// Write a function to convert a snake case string to camel case string.
fn snake_to_camel(word: String) -> String {
    let mut res = String::new();
    let mut first_char = true;
    for c in word.chars() {
        if c == '_' {
            first_char = true;
        } else {
            let c = if first_char { c.to_uppercase().next().unwrap() } else { c };
            res.push(c);
            first_char = false;
        }
    }
    res
}

/// Write a function to find the Eulerian number a(n, m).
fn eulerian_num(n: isize, m: isize) -> isize {
    if m >= n || n == 0 {
        return 0;
    }
    if m == 0 {
        return 1;
    }
    (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m)
}

/// Write a function to sort each subvector of strings in a given vector of vectors.
fn sort_sublists(input_list: Vec<Vec<String>>) -> Vec<Vec<String>> {
    let mut result = vec![];
    for sub in input_list {
        let mut sub_result = vec![];
        for x in sub {
            sub_result.push(x.to_string());
        }
        sub_result.sort_by(|a, b| a.to_lowercase().cmp(&b.to_lowercase()));
        result.push(sub_result);
    }
    return result;
}

/// Write a rsthon function to count true booleans in the given vector.
fn count(lst: Vec<bool>) -> isize {
