        .filter(|&&b| b == true)
        .count() as isize
}

/// Write a function to check if a string represents an integer or not.
fn check_integer(text: String) -> bool {
    text.trim().is_empty()
        || text.chars().all(|c| c.is_ascii_digit())
}

/// Write a function to convert a given tuple of positive integers into a single integer.
fn tuple_to_int(nums: (isize, isize, isize)) -> isize {
    return (nums.0 * 100) + (nums.1 * 10) + nums.2;
}

/// Write a function to convert a string to a vector of strings split on the space character.
fn string_to_list(string: String) -> Vec<String> {
    return string.split(" ").map(|x| x.to_string()).collect();
}

/// Write a rsthon function to find the element that appears only once in a sorted vector.
fn search(arr: Vec<isize>) -> isize {
    let mut XOR: isize = 0;
    for i in &arr {
        XOR = XOR ^ i;
    }
    return XOR;
}

/// Write a function to find the maximum absolute product between numbers in pairs of tuples within a given vector.
fn max_product_tuple(list1: Vec<(isize, isize)>) -> isize {
    list1.iter().map(|(x, y)| x * y).map(|y| y.abs()).max().unwrap()
}

/// Write a function to find the maximum difference between the number of 0s and number of 1s in any sub-string of the given binary string.
fn find_length(string: String) -> isize {
	let n = string.len();
	let mut current_sum = 0;
	let mut max_sum = 0;

	for i in 0..n {
		current_sum += if string.as_bytes()[i] == b'0' { 1 } else { -1 };

		if current_sum < 0 {
			current_sum = 0;
		}
		max_sum = max_sum.max(current_sum);
	}

	if max_sum == 0 {
		0
	} else {
		max_sum as isize
	}
}

/// Write a rsthon function to find the sum of common divisors of two given numbers.
fn sum(a: isize, b: isize) -> isize {
    let mut sum: isize = 0;
    for i in 1..a.min(b) {
        if a % i == 0 && b % i == 0 {
            sum += i
        }
    }
    sum
}

/// Write a function to multiply two integers.
fn multiply_int(x: isize, y: isize) -> isize {
    if y < 0 {
        -multiply_int(x, -y)
    } else if y == 0 {
        0
    } else if y == 1 {
        x
    } else {
        x + multiply_int(x, y - 1)
    }
}

/// Write a function to find words that are longer than n characters from a given vector of words.
fn long_words(n: isize, str: String) -> Vec<String> {
    let mut result = Vec::new();
    for word in str.split_whitespace() {
        if word.len() > n as usize {
            result.push(word.to_string());
        }
    }
    result
}

/// Write a function to calculate whether the matrix is a magic square.
fn magic_square_test(my_matrix: Vec<Vec<isize>>) -> bool {
    // First, we get the dimension of the matrix.
    let i_size = my_matrix[0].len();

    // Then we calculate the sum of each row and add it to a list.
    let mut sum_list = vec![];
    for lines in my_matrix.iter() {
        sum_list.push(lines.iter().sum::<isize>());
    }

    // We iterate through the columns of the matrix and add the elements of each column to the list.
    for col in 0..i_size {
        let mut sum_col = 0;
        for row in 0..i_size {
            sum_col += my_matrix[row][col];
        }
        sum_list.push(sum_col);
    }

    // We add the main diagonal to the list.
    let mut sum_main_diag = 0;
    for i in 0..i_size {
        sum_main_diag += my_matrix[i][i];
    }
    sum_list.push(sum_main_diag);

    // We add the anti-diagonal to the list.
    let mut sum_anti_diag = 0;
    for i in 0..i_size {
        sum_anti_diag += my_matrix[i][i_size - 1 - i];
    }
    sum_list.push(sum_anti_diag);

    // We remove the duplicate sums and check whether the list is empty.
    let sum_list_without_duplicates = sum_list.iter().cloned().collect::<std::collections::HashSet<_>>();
    if sum_list_without_duplicates.len() > 1 {
        return false;
    }

    return true;
}

/// Write a function to find the item with maximum frequency in a given vector.
fn max_occurrences(nums: Vec<isize>) -> isize {
    let mut dict = std::collections::HashMap::new();
    for i in nums {
        let count = dict.entry(i).or_insert(0);
        *count += 1;
    }
    let mut max_key = None;
    let mut max_value = 0;
    for (key, value) in dict.iter() {
        if *value > max_value {
            max_key = Some(*key);
            max_value = *value;
        }
    }
    match max_key {
        Some(key) => key,
        None => panic!("No elements in array"),
    }
}

/// Write a function to convert a vector to a string.
fn tup_string(tup1: Vec<String>) -> String {
    let mut str = "".to_string();
    for s in tup1 {
        str = str + &s;
    }
    str
}

/// Write a function to calculate the sum of the negative numbers of a given vector of numbers.
fn sum_negativenum(nums: Vec<isize>) -> isize {
    nums.iter().filter(|&&x| x < 0).sum()
}

/// Write a function to find the nth hexagonal number.
fn hexagonal_num(n: isize) -> isize {
	n * (2 * n - 1)
}

/// Write a rsthon function to check whether the given number can be represented as sum of non-zero powers of 2 or not.
fn is_Sum_Of_Powers_Of_Two(n: isize) -> bool {
    if n % 2 == 1 {
        return false;
    } else {
        return true;
    }
}

/// Write a function to count number items that are identical in the same position of three given vectors.
fn count_samepair(list1: Vec<isize>, list2: Vec<isize>, list3: Vec<isize>) -> isize {
    let mut result = 0;
    for i in 0..list1.len() {
        if list1[i] == list2[i] && list1[i] == list3[i] {
            result += 1;
        }
    }
    result
}

/// Write a rsthon function to find the maximum difference between any two elements in a given vector.
fn max_Abs_Diff(arr: Vec<isize>) -> isize {
    let mut min = arr[0];
    let mut max = arr[0];

    for i in 1..arr.len() {
        min = min.min(arr[i]);
        max = max.max(arr[i]);
    }
    max - min
}

/// Write a function that returns integers x and y that satisfy ax + by = n as a tuple, or return None if no solution exists.
fn find_solution(a: isize, b: isize, n: isize) -> Option<(isize, isize)> {
	let mut i = 0;
	while i * a <= n {
		if (n - (i * a)) % b == 0 {
			return Some((i, (n - (i * a)) / b));
		}
		i += 1;
	}
	None
}

/// Write a function to remove all elements from a given vector present in another vector.
fn remove_elements(list1: Vec<isize>, list2: Vec<isize>) -> Vec<isize> {
    list1.into_iter().filter(|x| !list2.contains(x)).collect()
}

/// Write a function to calculate the sum (n - 2*i) from i=0 to n // 2, for instance n + (n-2) + (n-4)... (until n-x =< 0).
fn sum_series(n: isize) -> isize {
  if n < 1 {
    return 0;
  } else {
    return n + sum_series(n - 2);
  }
}

/// Write a function to count the number of characters in a string that occur at the same position in the string as in the English alphabet (case insensitive).
fn count_char_position(str1: String) -> isize {
    let mut count_chars = 0;
    let str1 = str1.to_lowercase();
    for (index, c) in str1.chars().enumerate() {
        if (c as u32 - 'a' as u32) as isize == index as isize {
            count_chars += 1
        }
    }
    count_chars
}

/// Write a function that counts the number of pairs of integers in a vector that xor to an even number.
fn find_even_pair(A: Vec<isize>) -> isize {
    A.iter().enumerate()
        .flat_map(|(i, &a)| A.iter().enumerate().skip(i + 1).map(move |(j, &b)| (i, j, a, b)))
        .filter(|&(_, _, a, b)| (a ^ b) % 2 == 0)
        .count() as isize
}

/// Write a function to count the number of occurrences of a number in a given vector.
fn frequency(a: Vec<isize>, x: isize) -> isize {
    let mut count = 0;
    for i in a {
        if i == x {
            count += 1
        }
    }
    count
}

/// Write a function to find the sum of numbers in a vector within a range specified by two indices.
fn sum_range_list(list1: Vec<isize>, m: isize, n: isize) -> isize {
    let mut sum_range = 0;
    for i in m..=n {
        sum_range += list1[i as usize];
    }
    sum_range
}

/// Write a function to find the perimeter of a regular pentagon from the length of its sides.
fn perimeter_pentagon(a: isize) -> isize {
    a * 5
}

/// Write a function to count the number of occurence of the string 'std' in a given string.
fn count_occurance(s: String) -> isize {
    let count: isize = s.match_indices("std").count() as isize;
    return count;
}

/// Write a rsthon function to remove the characters which have odd index values of a given string.
fn odd_values_string(str: String) -> String {
    let mut result = String::new();
    for i in 0..str.len() {
        if i % 2 == 0 {
            result.push_str(&str[i..i + 1]);
        }
    }
    result
}

/// Write a function to find minimum of three numbers.
fn min_of_three(a: isize, b: isize, c: isize) -> isize {
    if (a <= b) && (a <= c) {
        a
    } else if (b <= a) && (b <= c) {
        b
    } else {
        c
    }
}

/// Write a rsthon function to check whether all the bits are unset in the given range or not.
fn all_Bits_Set_In_The_Given_Range(n: isize, l: isize, r: isize) -> bool {
    let mut num = (((1 << r) - 1) ^ ((1 << (l - 1)) - 1)) & n;
    if num == 0 {
        return true;
    }
    return false;
}

/// Write a function that takes in a string and character, replaces blank spaces in the string with the character, and returns the string.
fn replace_blank(str1: String, char: String) -> String {
    let mut res = String::new();
    for i in str1.chars() {
        if i == ' ' {
            res.push_str(char.as_str());
        } else {
            res.push(i);
        }
    }
    return res;
}

/// Write a function to find the volume of a cube given its side length.
fn volume_cube(l: isize) -> isize {
    l * l * l
}

/// Write a rsthon function to count the number of non-empty substrings of a given string.
fn number_of_substrings(str: String) -> isize {
    let mut str_len = 0;
    let mut res = 0;
    for s in str.chars() {
        str_len += 1;
        res += str_len;
    }
    res
}

