fn lps(str: String) -> isize {
    let n = str.len();
    let mut L = vec![vec![0; n]; n];
    for i in 0..n {
        L[i][i] = 1;
    }
    for cl in 2..=n {
        for i in 0..n-cl+1 {
            let j = i + cl - 1;
            if str.as_bytes()[i] == str.as_bytes()[j] {
                L[i][j] = L[i + 1][j - 1] + 2;
            } else {
                L[i][j] = L[i][j - 1].max(L[i + 1][j]);
            }
        }
    }
    L[0][n - 1]
}

