    let mut products = Vec::new();
    // 2. Loop through each element in the first vector.
    for &num1 in nums1.iter() {
        // 3. Loop through each element in the second vector.
        for &num2 in nums2.iter() {
            // 4. Append the product of the two elements to the products vector.
            products.push(num1 * num2);
        }
