/// Write a function to sort the given vector by using shell sort.
fn shell_sort(my_list: Vec<isize>) -> Vec<isize> {
    let mut my_list = my_list;
    let length = my_list.len();

    let mut gap = length / 2;

    while gap > 0 {
        for i in (gap..length).step_by(gap) {
            let current_item = my_list[i];
            let mut j = i;
            while j >= gap && my_list[j - gap] > current_item {
                my_list[j] = my_list[j - gap];
                j -= gap;
            }
            my_list[j] = current_item;
        }
        gap = gap / 2;
    }

    my_list
}

