    let mut start = 0;
    let mut end = array.len() - 1;
    while start <= end {
        let mid = (start + end) / 2;
        if (array[mid] != mid as isize) {
            if mid > 0 && array[mid - 1] == (mid - 1) as isize {
                return mid as isize;
            } else {
                end = mid - 1;
