/// Given a square matrix of size N*N given as a vector of vectors, where each cell is associated with a specific cost. A path is defined as a specific sequence of cells that starts from the top-left cell move only right or down and ends on bottom right cell. We want to find a path with the maximum average over all existing paths. Average is computed as total cost divided by the number of cells visited in the path.
fn maxAverageOfPath(cost: Vec<Vec<isize>>) -> f64 {
    let n = cost.len();
    let mut dp = vec![vec![0; n]; n];
    dp[0][0] = cost[0][0];
    for i in 1..n {
        dp[i][0] = dp[i - 1][0] + cost[i][0];
    }
    for j in 1..n {
        dp[0][j] = dp[0][j - 1] + cost[0][j];
    }
    for i in 1..n {
        for j in 1..n {
            dp[i][j] = std::cmp::max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
        }
    }
    let sum = dp[n - 1][n - 1];
    let num_cells = (2 * n) - 1;
    (sum as f64) / (num_cells as f64)
}

