fn lcs_of_three(X: String, Y: String, Z: String) -> isize {
    let m = X.len();
    let n = Y.len();
    let o = Z.len();
    let mut L = vec![vec![vec![0; o + 1]; n + 1]; m + 1];
    for i in 0..m + 1 {
        for j in 0..n + 1 {
            for k in 0..o + 1 {
                if i == 0 || j == 0 || k == 0 {
                    L[i][j][k] = 0;
                } else if X.chars().nth(i - 1) == Y.chars().nth(j - 1) && X.chars().nth(i - 1) == Z.chars().nth(k - 1) {
                    L[i][j][k] = L[i - 1][j - 1][k - 1] + 1;
                } else {
                    L[i][j][k] = std::cmp::max(
                        std::cmp::max(L[i - 1][j][k], L[i][j - 1][k]),
                        L[i][j][k - 1],
                    );
                }
            }
        }
    }
    L[m][n][o]
}

/// Write a function to check if the given vector represents min heap or not. https://www.geeksforgeeks.org/how-to-check-if-a-given-vector-represents-a-binary-heap/
fn check_min_heap(arr: Vec<isize>) -> bool {
    let n = arr.len();
    for i in 0..n / 2 {
        let left_child = 2 * i + 1;
        let right_child = 2 * i + 2;
        if left_child < n && arr[i] > arr[left_child] {
            return false;
        }
        if right_child < n && arr[i] > arr[right_child] {
            return false;
        }
    }
    true
}

/// Write a function to find the nth jacobsthal number. https://www.geeksforgeeks.org/jacobsthal-and-jacobsthal-lucas-numbers/ 0, 1, 1, 3, 5, 11, 21, 43, 85, 171, 341, 683, 1365, 2731, ...
fn jacobsthal_num(n: isize) -> isize {
    let mut dp = vec![0; (n + 1) as usize];
    dp[0] = 0;
    dp[1] = 1;
    for i in 2..=n {
        dp[i as usize] = dp[i as usize - 1] + 2 * dp[i as usize - 2];
    }
    dp[n as usize]
}

