/// Write a rsthon function to check whether the count of divisors is even. https://www.w3resource.com/rsthon-exercises/basic/rsthon-basic-1-exercise-24.php
fn count_divisors(n: isize) -> bool {
    let mut count = 0;
    for i in 1..=((n as f32).sqrt() as isize) + 2 {
        if n % i == 0 {
            if n / i == i {
                count = count + 1
            } else {
                count = count + 2
            }
        }
    }
    count % 2 == 0
}

